use std::{io::Write, path::PathBuf};

use clap::ValueEnum as _;

macro_rules! experimental {
    () => {
        "Экспериментально. CF: основная конфигурация из полной копии одним файлом через MS SQL Server, \
сжатые копии допускаются. Проверено на учебной базе (побайтно с выгрузкой Конфигуратора). Если \
конфигурацию базы обновляли динамически, CF содержит применённый вид, как выгрузка Конфигуратора; \
флаг --raw возвращает CONFIG как он хранится в базе. Восстановление проверено только на SQL Server 2022: в Docker для Linux и одним \
реальным запуском на сервере для Windows (результат побайтно совпал с результатом на Linux); \
другие версии сервера не проверялись. DT и 1CD: только небольшие учебные базы без пользователей, типовые \
конфигурации отклоняются. До восстановления отклоняются разностные и журнальные наборы, шифрованные \
(в том числе TDE) и составные (striped) копии, копии, помеченные повреждёнными, и снимки (отказ для снимков \
проверен на подставленных заголовках, настоящей копии-снимка не было). Обрезанную копию обнаруживает сам \
SQL Server во время восстановления: очистка выполняется, её итог выводится."
    };
}

pub(crate) const EXPERIMENTAL: &str = experimental!();

fn parse_backup_set(value: &str) -> Result<u32, String> {
    let position = value
        .parse::<u32>()
        .map_err(|_| "ожидается номер от 1 до 2147483647".to_owned())?;
    if !(1..=i32::MAX as u32).contains(&position) {
        return Err("ожидается номер от 1 до 2147483647".into());
    }
    Ok(position)
}

#[derive(Clone, Copy, clap::ValueEnum)]
pub(crate) enum Format {
    Cf,
    Dt,
    #[value(name = "1cd")]
    Onecd,
}

#[derive(clap::Subcommand)]
pub(crate) enum Command {
    #[command(about = "Проверить структуру резервной копии без её восстановления")]
    Inspect {
        #[arg(help = "Файл резервной копии MS SQL Server")]
        source: PathBuf,
    },
    #[command(
        about = "Восстановить копию через MS SQL Server и сохранить CF, DT или 1CD",
        after_help = concat!(experimental!(), "\n\n\
Путь SOURCE должен быть доступен службе SQL Server на машине сервера. Путь к копии может содержать знаки Юникода: на Windows проверены кириллица, апостроф, латиница-1 и эмодзи, на Linux кириллица, апостроф и эмодзи; путь не длиннее 259 единиц UTF-16 на сервере для Windows и 257 на сервере для Linux (SQL Server отвечает Msg 3057 на имя устройства длиннее 259); в сообщениях SQL Server на Windows знаки вне ANSI в имени показаны как ?: это ограничение клиента sqlcmd, сам путь передаётся верно. Измерено на одном стенде каждого вида.\n\
Если BAK содержит несколько наборов, выберите позицию через --backup-set; по умолчанию используется первая. Набор должен быть полной копией; для CF выбор набора проверен на копии с несколькими наборами.\n\
CF содержит основную конфигурацию, но не прикладные данные или расширения.\n\
Принимаются полные копии одним файлом с одной data- и одной log-частью; сжатые допускаются. Разностные и журнальные наборы, шифрованные копии и TDE, составные (striped) копии и копии, помеченные повреждёнными в заголовке, отклоняются до восстановления: временная база не создаётся. Снимки отклоняются так же, но на настоящей копии-снимке это не проверялось. Недоступный файл и файл, который SQL Server не признаёт резервной копией, отклоняются при осмотре, тоже до восстановления.\n\
Обрезанную копию SQL Server обнаруживает только при восстановлении (заголовки лежат в начале файла) и сам убирает за собой: очистка выполняется и её итог выводится.\n\
Если выгрузка прервана на середине большого результата, сервер ещё какое-то время держит сеанс убитого клиента, и база «используется». Очистка отключает сеансы только этой временной базы (после проверки точного имени и метки этого запуска) и удаляет её; если база всё же осталась, сообщение называет её, её размер по каталогу (если размер узнать не удалось, так и пишет: size unknown) и команду для администратора: ALTER DATABASE [имя] SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE [имя]; (если ALTER не проходит, потому что база ещё в состоянии восстановления, выполните один DROP) — на любом пути сбоя очистки, в том числе когда сервер не ответил вовремя. База без метки этого запуска (запись метки не состоялась) командой не удаляется: сообщение просит проверить, что это ваша база, и даёт ту же команду.\n\
Копия восстанавливается целиком: на сервере нужно место под всю базу (данные и журнал), даже если нужна только конфигурация.\n\
На SQL Server для Windows восстановление включает обнуление файла журнала: у файлов журнала нет мгновенной инициализации, и для журнала в десятки гигабайт это минуты. На медленном диске срока по умолчанию (см. ниже) может не хватить.\n\
CF и DT: CONFIG до 16 ГиБ, не более 1 млн файлов и 1024 частей на файл; строка ответа sqlcmd до 128 МиБ. Имена должны быть ASCII, Attributes — нулевым.\n\
Файл CONFIG больше 10 000 000 байт платформа хранит частями; такой файл получает время создания, время изменения и атрибуты нулевой части, как в выгрузке самой платформы. Части должны идти подряд с 0 и совпадать по Creation, Attributes и DataSize, Modified не должно убывать от части к части; иначе команда отказывает и называет поле и номер части. Для CF проверено на пяти приватных копиях баз типовых конфигураций (62 таких файла): записи совпали с нативной выгрузкой 1С по имени, содержимому, времени создания и изменения и атрибутам, раскладка страниц контейнера отличается.\n\
Динамическое обновление конфигурации при подключённом сеансе клиента не переписывает объекты в таблице Config, а оставляет рядом их копии (<объект>_dynupdate_<поколение>, versions_dynupdate_…, deleted_dynupdate_…) и запись DynamicallyUpdated; платформа сама их не применяет, выгрузка Конфигуратора применяет. Для CF по умолчанию они применяются так же: содержимое объекта берётся из копии (время создания, время изменения и атрибуты остаются от объекта), копия без объекта добавляет его (время берётся из копии: время выгрузки в базе не хранится), deleted_dynupdate_… убирает названные записи, копии и запись DynamicallyUpdated в результат не попадают. Без записи DynamicallyUpdated результат не меняется. Когда что-то применено, в stderr печатается одна строка с числами (поколений и операций: замен, добавлений, удалений), те же числа лежат в ответе stdout (dynamicUpdate). Флаг --raw возвращает CONFIG как он хранится в базе; с --to dt и --to 1cd он не допускается.\n\
Правило проверено на платформе 8.5.1.1529 и SQL Server 2022: на пятнадцати контрольных образцах (семь — от одного до трёх поколений подряд, замена, добавление и удаление объектов, два образца без записи DynamicallyUpdated; восемь — от четырёх до двенадцати поколений, в том числе объект, добавленный одним поколением и изменённый или удалённый более поздними, удаление нескольких объектов за одно обновление, удаление исходного объекта и удаления, которые следующие поколения перечисляют снова) и на одной настоящей базе; записи равны выгрузке Конфигуратора по имени, содержимому, времени создания и изменения и атрибутам (кроме времени добавленных объектов). Поколения применяются в порядке записи DynamicallyUpdated, а не в порядке их GUID. Проверено до двенадцати поколений; то, чего образцы не показали или чего платформа сама не производит (больше двенадцати поколений, копия из нескольких частей, имя, удалённое и снова записанное под тем же GUID, — платформа сама отказывает в таком обновлении, имя, скопированное и удалённое в одном поколении, необычное имя копии), команда отклоняет с причиной и номером поколения, без имён файлов, и предлагает --raw.\n\
У баз с режимом совместимости ≤8.3.14 CF из BAK отличается от нативной выгрузки контейнером (Format16 вместо 15, раскладка TOC), записи равны.\n\
1CD: CONFIG проходит через DT и загружается частями; действуют ограничения памяти и формата 1CD. Поддерживаемые локали: ru_RU, en_US.\n\
DT/1CD: остальные файловые разделы — до 1024 частей и 64 МиБ на файл, с нулевыми Attributes; действуют ограничения на данные и память.\n\
DT и 1CD — экспериментальный ограниченный перенос с управляемыми блокировками; обычные непустые пользователи и неподтверждённые хранилища не поддерживаются.\n\
Разделённые пользователи поддерживаются при одном общем реквизите с разделением данных и совместимости 80501; остальные общие реквизиты не поддерживаются.\n\
DT требует проверенный служебный профиль и целиком учитывает локальное двоичное хранилище.\n\
Если восстановление прервано (клиент sqlcmd убит, истёк срок, потерян канал), команда удаляет незавершённую временную базу yc_bak_<токен> этого запуска из каталога сервера: только её, по точному имени (те же символы и та же длина) и только в состоянии восстановления. Удалить такую базу может только член роли sysadmin: другим логинам, владельцу базы включая, SQL Server отказывает в DROP, поэтому команда отклоняет логин без этой роли сразу, до создания временной базы (если роль отозвали во время работы, сообщение говорит, что базу и её файлы должен удалить администратор). Файлы прерванного восстановления SQL Server удаляет не всегда: сообщение называет оставшиеся файлы с путями и размерами по каталогу, их нужно удалить вручную на машине SQL Server. Удаление, очистка сеансов и проверка роли sysadmin проверены на SQL Server 2022 для Linux в Docker, с SQL-логинами. На одном экземпляре SQL Server 2022 Developer для Windows (один компьютер), с Windows-аутентификацией (логин с ролью sysadmin), проверено удаление базы в состоянии восстановления и в состоянии ONLINE, а также удаление временной базы после Ctrl-C, Ctrl-Break и закрытия окна консоли в обеих фазах (восстановление и выгрузка). Не проверялись: отказ логину без роли sysadmin на Windows, роль sysadmin через группу Windows, другие версии SQL Server, macOS.\n\
Ctrl-C, SIGTERM и SIGHUP (на Windows: Ctrl-C, Ctrl-Break, закрытие окна консоли, выход из системы, выключение) во время работы с SQL Server команда обрабатывает как истёкший срок: останавливает свой клиент sqlcmd, удаляет временную базу теми же шагами, сразу пишет, что запрос принят, в конце сообщает итог очистки (если очистка не удалась, итог может занять несколько строк) и завершается тем же сигналом, а не кодом выхода: родитель, в том числе цикл оболочки, видит гибель от сигнала (оболочка показывает 130 для SIGINT, 143 для SIGTERM, 129 для SIGHUP; на Windows Ctrl-C и Ctrl-Break дают статус 0xC000013A; для закрытия окна, выхода из системы и выключения задуманы 129 и 143, но при закрытии окна процесс завершила сама Windows раньше, чем команда записала код, и статус в проверке не наблюдался). Результат (CF, DT или 1CD) не публикуется. Сигнал, который игнорировался при запуске (nohup, trap '' INT, фоновая задача неинтерактивной оболочки), остаётся игнорируемым: на него команда не реагирует и очистки по нему нет. Повторные сигналы во время очистки после прерывания игнорируются, а сама очистка ограничена 120 с на каждую команду; это больше срока, который дают docker stop (10 с по умолчанию) и systemd (90 с по умолчанию): при медленном сервере очистка может не успеть, процессу придёт SIGKILL, и база останется. Сигнал во время очистки после сбоя или после успешной выгрузки команда не игнорирует: первый она отмечает строкой (очистка продолжается), второй сигнал прекращает ожидание, и сообщение называет временную базу, её размер (или что он неизвестен) и команду для её удаления. Если сервер ещё восстанавливает базу (прерывание сразу после начала RESTORE), очистка повторяет попытки в пределах двух минут. Сигнал на локальном этапе DT в 1CD, который идёт после SQL-части и не наблюдается, обрывает команду сразу, как раньше, и оставляет рядом с результатом рабочие каталоги .yellowcode-*/source.dt и .yellowcode-restore-*/1Cv8.1CD; их можно удалить. Обработка сигналов проверена на Linux (SQL Server 2022 в Docker, SQL-логины) и на одном компьютере с Windows (SQL Server 2022 Developer, Windows-аутентификация). На Windows Ctrl-C и Ctrl-Break во время восстановления и во время выгрузки останавливают клиент sqlcmd (он делит консоль с командой), удаляют временную базу, результат не публикуется, процесс завершается статусом 0xC000013A, отчёт о сбое записан (исход failed, код 130); после прерванного восстановления SQL Server оставляет файлы базы (в проверке 6 ГБ журнала и 1 ГБ данных), сообщение называет их. Закрытие окна консоли завершает команду и клиент очистки за доли секунды, код выхода не наблюдался: временная база в проверке оказалась удалена, отчёта о сбое нет, файлы прерванного восстановления остаются; при закрытии окна, выходе из системы и выключении Windows даёт процессу лишь несколько секунд, поэтому очистка может не успеть. taskkill без /F ничего не делает (Windows отвечает, что процесс можно завершить только принудительно), запуск продолжается. Не проверялись: выход из системы и выключение, повторный сигнал во время очистки на Windows, Windows Terminal и PowerShell как родитель, macOS. Если процесс команды остановлен без возможности очистки (SIGKILL, потеря питания), ничего не удаляется: на Linux клиент sqlcmd доводит восстановление до конца, и остаётся база yc_bak_<токен> в состоянии ONLINE, только для чтения, с файлами полного размера; если клиент погиб вместе с командой, база остаётся в состоянии восстановления. На Windows проверена принудительная остановка процесса (taskkill /F): клиент погибает вместе с командой, и база остаётся в том состоянии, в котором её застала остановка (ONLINE, если восстановление уже закончилось; в состоянии восстановления, если оно шло). Имя базы выводится в stderr первой строкой каждого запуска. Удаление вручную от члена роли sysadmin: записать пути файлов (SELECT physical_name FROM sys.master_files WHERE database_id = DB_ID(N'yc_bak_<токен>')); если база в состоянии ONLINE, сначала выполнить ALTER DATABASE [yc_bak_<токен>] SET SINGLE_USER WITH ROLLBACK IMMEDIATE (иначе сеанс убитого клиента может удерживать базу: ошибка 3702); затем DROP DATABASE [yc_bak_<токен>]; и удалить записанные файлы, если они остались. На SQL Server для Windows это выполнено для базы в состоянии ONLINE (ALTER, затем DROP: база и её файлы исчезли) и для базы в состоянии восстановления (только DROP: он оставил два файла, и их удалили по записанным путям).\n\
Для SQL-аутентификации задайте --user и переменную SQLCMDPASSWORD; без --user используется доверенное подключение.\n\
Нужен Microsoft sqlcmd (ODBC, пакет mssql-tools18) и логин с ролью sysadmin: команда восстанавливает временную базу и должна уметь её удалить, поэтому логин без этой роли отклоняется сразу, до создания временной базы, с сообщением «the login must have the sysadmin role on the test server». go-sqlcmd не подходит: версия 1.10 не принимает параметр -f.\n\
Одна команда sqlcmd по умолчанию ограничена 30 минутами; срок меняет --sqlcmd-lifecycle-timeout. После сбоя удаление незавершённой базы и очистка получают не больше 2 минут каждое, и команда пишет в stderr, когда начинает каждое из них: если сервер завис, она кончается не позже чем через срок неудавшейся команды и ещё около четырёх минут. Очистка после успешной выгрузки этим пределом не ограничена: готовый результат ждёт её окончания, и она получает обычный срок команды (удаление большой базы может занять минуты). Если она не удалась, готовый результат (CF, DT или 1CD) не публикуется: команда завершается ошибкой, называет базу, её размер (или что он неизвестен) и команду для администратора.\n\
Если команда не справилась уже после начала работы с SQL Server, она сама записывает отчёт о сбое yellowcode-bak-failure-<время UTC>.log рядом с --output (имена файлов, баз, серверов, логинов и путей в нём заменены хешами, но каталог или файл с именем из 1–3 цифр может остаться видимым в тексте сообщений; что скрыто и что нет — в docs/bak-failure-report.md) и печатает путь к нему. --trace ФАЙЛ или переменная YELLOWCODE_TRACE записывают такую трассу в указанный новый файл и при успешном завершении.\n\
Пример: yellowcode bak convert 'C:\\Backup\\base.bak' --server localhost --to cf --output base.cf")
    )]
    Convert {
        #[arg(help = "Путь к BAK на машине SQL Server")]
        source: String,
        #[arg(long, help = "Имя экземпляра SQL Server")]
        server: String,
        #[arg(long, default_value = "1", value_parser = parse_backup_set, help = "Номер набора резервной копии в BAK (позиция из RESTORE HEADERONLY)")]
        backup_set: u32,
        #[arg(long, value_enum, help = "Формат результата")]
        to: Format,
        #[arg(long, help = "Путь к новому файлу на машине с Yellowcode")]
        output: PathBuf,
        #[arg(long, help = "Логин SQL Server; пароль берётся из SQLCMDPASSWORD")]
        user: Option<String>,
        #[arg(
            long,
            default_value = "sqlcmd",
            help = "Путь к Microsoft sqlcmd (ODBC)"
        )]
        sqlcmd: PathBuf,
        #[arg(long, value_parser = clap::value_parser!(u64).range(1..), help = "Общий срок каждой команды sqlcmd в секундах (по умолчанию 1800 + 120 на остановку); очистка получает отдельный срок")]
        sqlcmd_lifecycle_timeout: Option<u64>,
        #[arg(
            long,
            help = "Доверять сертификату SQL Server без проверки его цепочки"
        )]
        trust_server_certificate: bool,
        #[arg(
            long,
            value_name = "FILE",
            help = "Записать трассу выполнения в новый файл и при успехе (или задайте переменную YELLOWCODE_TRACE)"
        )]
        trace: Option<PathBuf>,
        #[arg(
            long,
            allow_hyphen_values = true,
            help = "Только для 1CD: бюджет памяти восстановления DT (auto или B/KiB/MiB/GiB); не ограничивает MS SQL Server"
        )]
        memory_limit: Option<String>,
        #[arg(
            long,
            help = "Только для CF: вернуть CONFIG как он хранится в базе, не применяя остатки динамического обновления"
        )]
        raw: bool,
    },
}

impl Command {
    pub(crate) fn usage_error(&self) -> Option<clap::Error> {
        let Command::Convert { raw: true, to, .. } = self else {
            return None;
        };
        if matches!(to, Format::Cf) {
            return None;
        }
        let name = to.to_possible_value()?.get_name().to_owned();
        let mut cli = <crate::Cli as clap::CommandFactory>::command();
        cli.build();
        let convert = cli
            .find_subcommand_mut("bak")?
            .find_subcommand_mut("convert")?;
        Some(convert.error(
            clap::error::ErrorKind::ArgumentConflict,
            format!("the argument '--raw' cannot be used with '--to {name}': only a CF has a stored form to return"),
        ))
    }
}

pub(crate) fn run(
    command: Command,
    out: &mut dyn Write,
    err: &mut dyn Write,
) -> yellowcode_core::Result<()> {
    match command {
        Command::Inspect { source } => yellowcode_core::plain::bak::inspect(&source, out),
        Command::Convert {
            source,
            server,
            backup_set,
            to,
            output,
            user,
            sqlcmd,
            sqlcmd_lifecycle_timeout,
            trust_server_certificate,
            trace: _,
            memory_limit,
            raw,
        } => {
            if memory_limit.is_some() && !matches!(to, Format::Onecd) {
                return Err("--memory-limit is only for 1CD conversion".into());
            }
            let request = yellowcode_core::plain::bak::SqlConvertRequest {
                backup_path: source,
                server,
                output,
                user,
                sqlcmd,
                lifecycle_timeout: sqlcmd_lifecycle_timeout.map(std::time::Duration::from_secs),
                trust_server_certificate,
            };
            match to {
                Format::Cf => yellowcode_core::plain::bak::convert_with_options(
                    request,
                    backup_set,
                    &yellowcode_core::plain::bak::CfOptions {
                        view: if raw {
                            yellowcode_core::plain::bak::CfView::Stored
                        } else {
                            yellowcode_core::plain::bak::CfView::Applied
                        },
                    },
                    out,
                    err,
                ),
                Format::Dt => yellowcode_core::plain::bak::convert_dt_with_backup_set(
                    request, backup_set, out, err,
                ),
                Format::Onecd => {
                    yellowcode_core::plain::bak::convert_onecd_with_memory_and_backup_set(
                        request,
                        memory_limit,
                        backup_set,
                        out,
                        err,
                    )
                }
            }
        }
    }
}
